       margin: 0 0 0.35rem;
       color: var(--primary);
       font-size: 0.9rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3.4rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .subhead {
       max-width: 36rem;
       margin: 0;
       color: var(--muted);
       font-size: 1.05rem;
       line-height: 1.6;
     }

     .preview-card {
       display: grid;
       gap: 1rem;
       padding: 1rem;
       border: 1px solid rgba(216, 224, 238, 0.9);
       border-radius: calc(var(--radius) + 8px);
       background: var(--surface);
