       aspect-ratio: 16 / 9;
       border: 1px solid rgba(216, 224, 238, 0.9);
     }

     .image-frame img {
       display: block;
       width: 100%;
       height: 100%;
       object-fit: cover;
     }

     figcaption {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
       align-items: center;
       justify-content: space-between;
       padding: 0.2rem 0.25rem 0;
     }

     .meta h2 {
       margin: 0 0 0.25rem;
       font-size: 1.2rem;
     }

     .meta p {
       margin: 0;
       color: var(--muted);
     }

     .actions {
       display: flex;
       gap: 0.75rem;
       flex-wrap: wrap;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.85rem 1.15rem;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       transition: transform 0.15s ease, background-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
     }

     button:focus-visible,
     summary:focus-visible,
     a:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .trigger {
       background: var(--danger);
       color: #fff;
       box-shadow: 0 10px 24px rgba(214, 69, 69, 0.25);
     }

     .trigger:hover {
       background: var(--danger-hover);
     }

     .trigger:active,
     .ghost:active,
     .confirm:active {
       transform: translateY(1px);
     }

     .ghost {
       background: #edf2fb;
       color: var(--text);
     }

     .ghost:hover {
       background: #dfe8f7;
     }

     dialog {
       width: min(92vw, 30rem);
       padding: 0;
       border: 1px solid rgba(216, 224, 238, 0.9);
       border-radius: 28px;
       background: var(--surface-solid);
       color: var(--text);
       box-shadow: var(--shadow);
     }

     dialog::backdrop {
       background: rgba(14, 24, 48, 0.5);
       backdrop-filter: blur(6px);
     }

     .dialog-shell {
       padding: 1.5rem;
       display: grid;
       gap: 1rem;
     }

     .dialog-copy {
       display: grid;
       gap: 0.4rem;
     }

     .dialog-copy h2 {
       margin: 0;
       font-size: 1.4rem;
       line-height: 1.2;
       letter-spacing: -0.03em;
     }

     .dialog-copy p {
       margin: 0;
       color: var(--muted);
       line-height: 1.6;
     }

     .dialog-actions {
       display: flex;
       justify-content: flex-end;
       gap: 0.75rem;
       flex-wrap: wrap;
       padding-top: 0.25rem;
     }

     .confirm {
       background: var(--danger);
       color: #fff;
     }

     .confirm:hover {
       background: var(--danger-hover);
     }

     .state {
       min-height: 1.5rem;
       margin: 0;
       color: var(--muted);
       font-size: 0.95rem;
     }

     .state[aria-live] {
       padding-left: 0.25rem;
     }

     @media (max-width: 640px) {
       main {
         width: min(100% - 1rem, 960px);
         padding-top: 3.5rem;
       }

       .preview-card,
       .dialog-shell {
         padding: 0.85rem;
       }

       figcaption {
         align-items: start;
       }

       .actions,
       .dialog-actions {
         width: 100%;
       }

       .actions button,
       .dialog-actions button {
         flex: 1 1 0;
       }
     }

     @media (forced-colors: active) {
       :root {
         --focus: Highlight;
       }

       .preview-card,
       dialog {
         border: 1px solid CanvasText;
       }

       button {
         border: 1px solid ButtonText;
       }

       dialog::backdrop {
         background: rgba(0, 0, 0, 0.65);
       }
     }
