       <div class="dialog-actions">
         <button class="ghost" type="button" data-close>Cancel</button>
         <button class="confirm" type="button" data-confirm>Delete</button>
       </div>
     </div>
   </dialog>

   <script>
     const dialog = document.getElementById('delete-dialog');
     const trigger = document.querySelector('.trigger');
     const cancelButton = dialog.querySelector('[data-close]');
     const confirmButton = dialog.querySelector('[data-confirm]');
     const status = document.getElementById('status');

     function openDialog() {
       dialog.showModal();
       cancelButton.focus();
     }

     trigger.addEventListener('click', openDialog);

     cancelButton.addEventListener('click', () => {
       dialog.close('cancel');
     });

     confirmButton.addEventListener('click', () => {
       dialog.close('delete');
     });

     dialog.addEventListener('cancel', (event) => {
       event.preventDefault();
       dialog.close('cancel');
     });

     dialog.addEventListener('close', () => {
       if (dialog.returnValue === 'delete') {
         status.textContent = 'Image deleted from your library.';
       }
     });
